<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>IMF World Economic Outlook Trends 2024–2026 - Infographic</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { background: #f5f5f5; font-family: 'Helvetica Neue', Arial, sans-serif; }
    .poster {
      width: 841px;
      height: 1189px;
      background: #ffffff;
      margin: 20px auto;
      position: relative;
      overflow: hidden;
      box-shadow: 0 4px 24px rgba(0,0,0,0.12);
    }
    .section {
      position: absolute;
      left: 0; top: 0; right: 0; bottom: 0;
    }
    .section-inner {
      position: absolute;
    }
    /* Header band */
    #header-band {
      background: #002244;
      height: 100px;
      top: 0;
      display: flex;
      flex-direction: column;
      justify-content: center;
      padding: 0 36px;
    }
    #header-band .conf-label {
      font-size: 11px;
      letter-spacing: 2px;
      color: #8aa8c8;
      text-transform: uppercase;
      margin-bottom: 6px;
    }
    #header-band .main-title {
      font-size: 26px;
      font-weight: 700;
      color: #ffffff;
      line-height: 1.2;
    }
    #header-band .subtitle {
      font-size: 12px;
      color: #8aa8c8;
      margin-top: 6px;
    }
    /* Risk banner */
    #risk-banner {
      background: #7d3200;
      height: 40px;
      top: 100px;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 16px;
    }
    #risk-banner .risk-label {
      font-size: 13px;
      letter-spacing: 2px;
      color: #ffcc88;
      text-transform: uppercase;
      font-weight: 600;
    }
    #risk-banner .risk-text {
      font-size: 14px;
      color: #ffffff;
      font-weight: 700;
    }
    /* Divider */
    .divider {
      position: absolute;
      left: 36px; right: 36px;
      height: 1px;
      background: #e0e0e0;
    }
    /* Infographic containers */
    .infographic-wrap {
      position: absolute;
      overflow: hidden;
    }
    /* Layout zones */
    #zone-chart {
      top: 156px;
      height: 300px;
    }
    #zone-metrics {
