</head>
<body>
<div class="poster">

  <!-- Header Band -->
  <div class="section" id="header-band">
    <div class="section-inner">
      <div class="conf-label">IMF–World Bank Annual Meetings Research Symposium</div>
      <div class="main-title">Global Economy in the Shadow of War</div>
      <div class="subtitle">World Economic Outlook Trends &nbsp;|&nbsp; 2024 – 2026 &nbsp;|&nbsp; Eight WEO Editions Synthesized</div>
    </div>
  </div>

  <!-- Risk Banner -->
  <div class="section" id="risk-banner">
    <div class="section-inner" style="display:flex;align-items:center;gap:16px;">
      <span class="risk-label">Risk Balance</span>
      <span class="risk-text">— Across all 8 WEO editions reviewed: tilted to the downside —</span>
    </div>
  </div>

  <!-- SECTION 1: Growth Trajectory Chart -->
  <div class="infographic-wrap" id="zone-chart">
    <div id="chart-container"></div>
  </div>

  <!-- SECTION 2: Key Metrics Row -->
  <div class="infographic-wrap" id="zone-metrics">
    <div id="metrics-container"></div>
  </div>

  <!-- SECTION 3: Risk Factors -->
  <div class="infographic-wrap" id="zone-risks">
    <div id="risks-container"></div>
  </div>

  <!-- SECTION 4: Policy Evolution -->
  <div class="infographic-wrap" id="zone-policy">
    <div id="policy-container"></div>
  </div>

  <!-- SECTION 5: Thematic Focus -->
  <div class="infographic-wrap" id="zone-themes">
    <div id="themes-container"></div>
  </div>

  <!-- Footer -->
  <div id="footer">
    <span class="footer-text">Sources: IMF World Economic Outlook — July 2024 through April 2026</span>
    <span class="footer-text">N = 8 WEO editions reviewed</span>
  </div>

</div>

<script src="/app/vendor/infographic.min.js"></script>
<script>

// ── Palette ──────────────────────────────────────────────────────────────────
const C = {
  imfBlue:    '#002244',
  midBlue:    '#1a4a8a',
  lightBlue:  '#4a7fc0',
  steelBlue:  '#6b9bc8',
  paleBlue:   '#d8e8f5',
  amber:      '#c45a00',
  lightAmber: '#ffcc88',
  warmOrange: '#e07020',
  redOrange:  '#7d3200',
  warmBg:     '#fff8f0',
  gray1:      '#f5f5f5',
  gray2:      '#e8e8e8',
  gray3:      '#cccccc',
  gray4:      '#888888',
  gray5:      '#444444',
  gray6:      '#222222',
  white:      '#ffffff',
  black:      '#000000',
};

// ── Section label helper ─────────────────────────────────────────────────────
function sectionLabel(parentId, text, y) {
  const el = document.createElement('div');
  el.style.cssText = `
    position: absolute;
    left: 36px; top: ${y}px;
    font-size: 10px; letter-spacing: 2px;
    color: ${C.steelBlue}; text-transform: uppercase;
    font-weight: 600;
  `;
  el.textContent = text;
  document.getElementById(parentId).appendChild(el);
}

// ── 1. GROWTH TRAJECTORY CHART ───────────────────────────────────────────────
sectionLabel('zone-chart', 'Section 1 — Global Growth Projections: A Narrow Band of Mediocrity', 6);

const chartData = `
infographic chart-line-plain-text
data
  title Global GDP Growth Trajectory — 8 WEO Editions
  desc Growth forecasts held within 3.0–3.3% band; well below the pre-pandemic average of ~3.8%
  values
    - label Jul '24
      value 3.2
      desc Sticky Spot Update
    - label Oct '24
      value 3.2
      desc Policy Pivot, Rising Threats
    - label Jan '25
      value 3.3
      desc Divergent and Uncertain
    - label Apr '25
      value 3.1
      desc Critical Juncture
    - label Jul '25
      value 3.0
      desc Tenuous Resilience
    - label Oct '25
      value 3.1
      desc Flux, Prospects Dim
    - label Jan '26
      value 3.3
      desc Steady amid Divergent Forces
    - label Apr '26
      value 3.0
      desc Shadow of War
theme
  palette ${C.imfBlue} ${C.warmOrange} ${C.lightAmber}
`;

const chartC = new AntVInfographic.Infographic({
  container: '#chart-container',
  width: '769',
  height: '280',
});
chartC.render(chartData.trim());

// ── 2. KEY METRICS ───────────────────────────────────────────────────────────
sectionLabel('zone-metrics', 'Key Figures at a Glance', 6);

const metricsData = `
infographic list-grid-badge-card
data
  title Key Figures
  lists
    - label Global Growth 2025
      value 3.0%
      desc WEO July 2025 Update
      icon chart line down
    - label Global Growth 2026
      value 3.3%
      desc WEO January 2026 Update
      icon chart line up
    - label Global Growth 2027
      value 3.2%
      desc WEO January 2026 Update
      icon chart line
    - label WEO Editions Reviewed
      value 8
      desc IMF WEO series, Jul 2024 – Apr 2026
      icon document text
    - label Pre-pandemic Average
      value 3.8%
      desc Historical baseline (2010–2019)
      icon history
    - label Risk Balance
      value ↓ Downside
      desc All 8 editions consistent
      icon warning triangle
theme
  palette ${C.imfBlue} ${C.warmOrange} ${C.steelBlue}
`;

const metricsC = new AntVInfographic.Infographic({
  container: '#metrics-container',
  width: '769',
  height: '96',
});
metricsC.render(metricsData.trim());

// ── 3. RISK FACTORS ──────────────────────────────────────────────────────────
sectionLabel('zone-risks', 'Dominant Downside Risks — Persistent Across All Editions', 6);

const risksData = `
infographic list-row-horizontal-icon-arrow
data
  title Key Risk Factors Flagged Across 8 WEO Editions
  desc Trade wars · Geopolitical fractures · Tech re-evaluation · Stubborn services inflation
  lists
    - label Trade Policy Escalation
      desc Tariff increases and retaliatory measures intensified from 2025; front-loading temporarily masks damage
      icon global line
    - label Geopolitical Tensions
      desc Middle East conflict, broader security concerns, and the war referenced in April 2026 title
      icon warning circle
    - label Technology Re-evaluation
      desc Risk of correction in AI and tech investment expectations after elevated buildup
      icon cpu line
    - label Persistent Services Inflation
      desc US return to target more gradual than peer economies; services inflation particularly sticky
      icon trend up
theme
  palette ${C.redOrange} ${C.amber} ${C.warmOrange}
`;

const risksC = new AntVInfographic.Infographic({
  container: '#risks-container',
  width: '769',
  height: '186',
});
risksC.render(risksData.trim());

// ── 4. POLICY EVOLUTION ─────────────────────────────────────────────────────
sectionLabel('zone-policy', 'Policy Priorities — An Evolving Hierarchy', 6);

const policyData = `
infographic sequence-roadmap-vertical-simple
data
  title IMF Policy Guidance Shifted Over Eight WEO Editions
  desc Fiscal buffers → Structural reforms → Defense-spending trade-offs
  sequences
    - label Mid-2024
      desc Manage disinflation; begin monetary easing carefully
    - label Late 2024
      desc Pivot monetary policy; ensure fiscal sustainability
    - label Early 2025
      desc Rebuild fiscal buffers; address demographic and gender gaps
    - label Mid-2025
      desc Restore confidence and predictability amid tariff uncertainty
    - label Late 2025
      desc Strengthen policy frameworks; cautious industrial policy
    - label Early 2026
      desc Agile policy; manage defense-spending trade-offs; foundations for recovery
theme
  palette ${C.imfBlue} ${C.midBlue} ${C.lightBlue}
`;

const policyC = new AntVInfographic.Infographic({
  container: '#policy-container',
  width: '769',
  height: '186',
});
policyC.render(policyData.trim());

// ── 5. THEMATIC FOCUS ────────────────────────────────────────────────────────
sectionLabel('zone-themes', 'Special Analytical Themes Across WEO Editions', 6);

const themesData = `
infographic list-grid-candy-card-lite
data
  title Rotating Analytical Deep-Dives
  lists
    - label Monetary Policy & Disinflation
      desc Global monetary pivot — how central banks navigated the exit from post-COVID tightening
    - label Social Acceptability of Reforms
      desc Structural reform agendas require democratic legitimacy and social buy-in
    - label Industrial Policy Effectiveness
      desc Effectiveness and fiscal cost of national industrial policy interventions
    - label Demographic Challenges
      desc Aging populations, gender disparities, and migrant skill alignment in labor markets
theme
  palette ${C.imfBlue} ${C.steelBlue} ${C.midBlue}
`;

const themesC = new AntVInfographic.Infographic({
  container: '#themes-container',
  width: '769',
  height: '146',
});
themesC.render(themesData.trim());

// ── Add structural lines / dividers via DOM ───────────────────────────────────
['zone-chart','zone-metrics','zone-risks','zone-policy','zone-themes'].forEach(id => {
  const el = document.getElementById(id);
  const divider = document.createElement('div');
  divider.style.cssText = `
    position: absolute; bottom: 0; left: 0; right: 0;
    height: 1px; background: ${C.gray2};
  `;
  el.appendChild(divider);
});

document.fonts?.ready.then(() => {
  console.log('Fonts loaded');
}).catch(e => console.log('Font load skipped:', e.message));

</script>
</body>
</html>
