const puppeteer = require('puppeteer');
const path = require('path');
const fs = require('fs');

async function renderPoster() {
  const browser = await puppeteer.launch({
    headless: true,
    args: [
      '--no-sandbox',
      '--disable-setuid-sandbox',
      '--disable-dev-shm-usage',
      '--disable-gpu',
    ],
    executablePath: process.env.PUPPETEER_EXECUTABLE_PATH || undefined,
  });

  const page = await browser.newPage();

  // A0 portrait: 841mm x 1189mm at 300dpi = 9933 x 14043 pixels
  // At 96dpi (screen): 841mm = 319px, 1189mm = 451px (but let's use 150dpi for quality)
  const widthPx = Math.round(841 / 25.4 * 150);  // 4964 px
  const heightPx = Math.round(1189 / 25.4 * 150); // 7016 px

  await page.setViewport({
    width: widthPx,
    height: heightPx,
    deviceScaleFactor: 1,
  });

  const htmlPath = path.resolve(__dirname, 'imf-weo-poster.html');
  const fileUrl = 'file://' + htmlPath;

  console.log('Loading:', fileUrl);
  await page.goto(fileUrl, { waitUntil: 'networkidle0', timeout: 30000 });

  // Wait for fonts and all infographics to render
  await page.waitForTimeout(3000);

  // Verify all containers are populated
  const containers = ['#chart-container', '#metrics-container', '#risks-container', '#policy-container', '#themes-container'];
  for (const id of containers) {
    const hasContent = await page.evaluate((sel) => {
      const el = document.querySelector(sel);
      return el && el.children.length > 0;
    }, id);
    console.log(`${id}: ${hasContent ? 'OK' : 'EMPTY'}`);
  }

  // Take screenshot
  const outputPath = path.resolve(__dirname, 'final_poster.png');
  await page.screenshot({
    path: outputPath,
    type: 'png',
    fullPage: true,
    omitBackground: false,
  });

  console.log('Saved to:', outputPath);

  const stats = fs.statSync(outputPath);
  console.log('File size:', (stats.size / 1024 / 1024).toFixed(2), 'MB');

  await browser.close();
}

renderPoster().catch(e => {
  console.error('Render failed:', e);
  process.exit(1);
});

